using System.Collections.Generic;

namespace WarsOfLibertyLauncher.Localization;

/// <summary>
/// The achievements' strings (design 121, <c>docs/design_logros</c>): every medal's name and
/// condition, keyed <c>Achv_&lt;id&gt;</c> and <c>AchvCond_&lt;id&gt;</c> by the server's id, the group
/// headings (<c>AchvGroup_&lt;id&gt;</c>), and the section, notice and celebration texts. The names are
/// the ones the design's author chose in both languages. An id the server sends that has no entry
/// here is shown with the English the server sends with it (<see cref="TryGet"/>), so a new medal
/// never reads as a raw key. Spanish is es-419 with tuteo.
/// </summary>
public static partial class Strings
{
    /// <summary>The value in the launcher's language when the key exists; false when it does not,
    /// for a text the caller has its own fallback for.</summary>
    public static bool TryGet(string key, out string value)
    {
        if (Table.TryGetValue(key, out var langs))
        {
            if (langs.TryGetValue(Language, out var localized)) { value = localized; return true; }
            if (langs.TryGetValue(LangEn, out var fallback)) { value = fallback; return true; }
        }
        value = "";
        return false;
    }

